35	export function planInstall(packs, ids, installed, { engineVersion = ENGINE_VERSION } = {}) {
36	  const byId = new Map(packs.map((p) => [p.id, p]));
37	  const stamped = installed?.packVersions ?? {};
38	  const install = [];
39	  const refused = [];
40	  for (const id of ids ?? []) {
41	    const pack = byId.get(id);
42	    if (!pack) { refused.push({ id, why: `"${id}" names no canon pack` }); continue; }
43	    if (typeof stamped[id] === 'number') {
44	      refused.push({ id, why: `"${id}" is already installed at version ${stamped[id]} — that is an update, not an install` });
45	      continue;
46	    }
47	    const needs = pack.minEngineVersion;
48	    if (typeof needs === 'number' && needs > engineVersion) {
49	      refused.push({ id, why: `"${id}" needs engine ${needs}; this repo runs engine ${engineVersion}` });
